style.css:
body {
         font-family: 'Arial', sans-serif; /* Замените Arial на предпочитаемый шрифт */
     } input, textarea {
         background-color: rgba(240, 248, 255, 0.9); /* Полупрозрачный фон для текстовых полей */
         border: 1px solid #1e90ff; /* Цвет рамки */
         padding: 10px; /* Внутренний отступ */
     }
     button, a {
         transition: background-color 0.3s ease;
     }
